() => {
  const n = navigator.userAgentData,
    r = n?.brands ?? [];
  return {
    ua: navigator.userAgent,
    secChUa: r.map(s => `"${s.brand}";v="${s.version}"`).join(", "),
    mobile: n?.mobile ? "?1" : "?0",
    platform: n?.platform ? `"${n.platform}"` : '"Windows"',
    lang: navigator.language || "en-US"
  };
}
